mapper.select:
select `f`.*,u.real_name,u.image_url from `friend` f   left join `user` u on f.friend_id = u.id
where f.status = 2


        and f.user_id = #{userId}


        and u.real_name like concat('%',#{realName},'%')


        and f.friend_id = #{friendId}




    order by f.update_time desc

select `f`.*,u.real_name,u.image_url from `friend` f   left join `user` u on f.user_id = u.id
where 1=1

    and f.user_id != #{userId}


    and u.real_name like concat('%',#{realName},'%')


    and f.friend_id = #{friendId}


    and f.accept_add_user_id = #{acceptAddUserId}


    and f.active_add_user_id = #{activeAddUserId}


    and f.status = #{status}

order by f.status asc,f.update_time desc
